"""Plot an overlay of trace.csv files generated by pd_step_test.py (no Isaac needed)."""
import argparse, json
from pathlib import Path
import numpy as np
import matplotlib.pyplot as plt

p = argparse.ArgumentParser(description=__doc__)
p.add_argument("traces", type=Path, nargs="+")
p.add_argument("--out", type=Path, default=Path("step_comparison.png"))
a = p.parse_args()
fig, axes = plt.subplots(3, 1, sharex=True, figsize=(9, 7), layout="constrained")
condition = None
for path in a.traces:
    meta = json.loads((path.parent/"settings.json").read_text())
    test = (meta["joint"], meta["fixture"])
    if condition and test != condition: raise ValueError("Compare the same joint and fixture.")
    condition = test
    j = meta["joint"].split("_")[0]
    d = np.genfromtxt(path, names=True, delimiter=",", dtype=None, encoding="utf-8")
    label = f"Kp {meta['kp']:g}, Kd {meta['kd']:g}"
    t = d["time_s"]
    axes[0].plot(t, d[j+"_angle_rad"], label=label)
    if path == a.traces[0]: axes[0].step(t,d[j+"_target_rad"],where="pre",color="k",ls="--",label="Target")
    axes[1].plot(t, d[j+"_effort_est_Nm"], label=label)
    axes[2].plot(t, d["foot_fz_N"], label=label)
for ax, unit in zip(axes,["Angle (rad)", "Drive estimate (N·m)", "Vertical contact force (N)"]):
    ax.set_ylabel(unit);ax.grid(alpha=.2);ax.legend()
axes[-1].set_xlabel("Time (s)")
fig.suptitle(f"{condition[0]} step response · {condition[1]}")
fig.savefig(a.out,dpi=180)
print(a.out.resolve())
